  const sunday = new Date("2026-11-22T12:00:00Z"); // Sunday noon UTC
  assert.equal(canShip(sunday), false);
});

test("canShip refuses deploys before business hours", () => {
  const early = new Date("2026-11-17T08:00:00Z"); // Monday 8 AM UTC
  assert.equal(canShip(early), false);
});

test("canShip refuses deploys after business hours", () => {
  const late = new Date("2026-11-17T18:00:00Z"); // Monday 6 PM UTC
  assert.equal(canShip(late), false);
});

test("canShip allows deploys during business hours on weekdays", () => {
  const businessHours = new Date("2026-11-17T14:00:00Z"); // Monday 2 PM UTC
  assert.equal(canShip(businessHours), true);
